 async function clarifyMeaning(q,answer){if(question!==q)return;const ticket=++meaningSerial,epoch=generation;const m=await call('if-space/meaning',{...meaningInput(q.text),...q.answers,...answer});if(question!==q||ticket!==meaningSerial||epoch!==generation||!i4.isUser())return;if(m.status==='supported')await accept(m.payload,q.done,m);else {question={...q,meaning:m,answers:{...q.answers,...answer}};render();}}
 function meaningInput(text){return {text,context:{...(active?{node:active}:{}),selected:selection.payload().options},aliases:rows('node').map(n=>({ref:n.ref,name:name(n)})).filter(a=>a.name!==selection.find(a.ref)?.title),antecedent,...(pending?{proposal_id:pending}:{})};}
